use crate::api::client::ApiClient;
use crate::constants;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

pub struct StatsCommand;

fn aggregate_by_project(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals: HashMap<String, i64> = HashMap::new();
    for entry in entries.iter().filter(|entry| !entry.is_running()) {
        let project_name = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| constants::NO_PROJECT.to_string());
        *totals.entry(project_name).or_default() += entry.duration;
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(name_a, seconds_a), (name_b, seconds_b)| {
        seconds_b.cmp(seconds_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

impl StatsCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = aggregate_by_project(&entries);
        let grand_total: i64 = totals.iter().map(|(_, seconds)| seconds).sum();

        for (project_name, seconds) in totals {
            println!(
                "{}  {}",
                utilities::format_duration_compact(seconds),
                project_name
            );
        }
        println!(
            "{}  Total",
            utilities::format_duration_compact(grand_total)
        );
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::api::client::MockApiClient;
    use crate::models::{Project, TimeEntry};
    use chrono::{TimeZone, Utc};

    fn entry(duration: i64, project: Option<&str>) -> TimeEntry {
        TimeEntry {
            id: duration,
            description: String::new(),
            start: Utc.timestamp_opt(0, 0).single().unwrap(),
            stop: Some(Utc.timestamp_opt(duration.max(0), 0).single().unwrap()),
            duration,
            billable: false,
            workspace_id: 1,
            tags: vec![],
            project: project.map(|name| Project {
                id: 1,
                name: name.to_string(),
                workspace_id: 1,
                client: None,
                is_private: false,
                active: true,
                at: Utc.timestamp_opt(0, 0).single().unwrap(),
                created_at: Utc.timestamp_opt(0, 0).single().unwrap(),
                color: "#000000".to_string(),
                billable: None,
            }),
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn aggregates_running_entries_out_and_sorts_by_duration_then_name() {
        let totals = aggregate_by_project(&[
            entry(2700, Some("Zed")),
            entry(2700, Some("Alpha")),
            entry(3600, None),
            entry(-1, Some("Ignored")),
        ]);
        assert_eq!(
            totals,
            vec![
                (constants::NO_PROJECT.to_string(), 3600),
                ("Alpha".to_string(), 2700),
                ("Zed".to_string(), 2700),
            ]
        );
    }

    #[tokio::test]
    async fn stats_uses_normalized_filtered_entries() {
        let mut api_client = MockApiClient::new();
        let (expected_since, expected_until) =
            utilities::normalize_time_entry_list_filters(Some("today".into()), Some("today".into()))
                .unwrap();
        api_client
            .expect_get_time_entries_filtered()
            .withf(move |since, until| *since == expected_since && *until == expected_until)
            .returning(|_, _| Ok(Vec::new()));

        StatsCommand::execute(api_client, Some("today".into()), Some("today".into()))
            .await
            .unwrap();
    }
}

