#[test]
fn entry_stats_parses_json_and_dates() {
    let cmd = Cli::try_parse_from([
        "toggl",
        "entry",
        "stats",
        "--since",
        "yesterday",
        "--until",
        "today",
        "--json",
    ])
    .expect("should parse");
    match cmd.cmd {
        Command::Entry {
            action: EntryAction::Stats {
                since: Some(since),
                until: Some(until),
                json: true,
            },
        } => {
            assert_eq!(since, "yesterday");
            assert_eq!(until, "today");
        }
        other => panic!("unexpected parse result: {other:?}"),
    }
}

