    );
}

fn print_row(
    id: Option<i64>,
    start: &str,
    seconds: i64,
    billable: bool,
    description: &str,
    project_name: &str,
) {
    let duration = format_duration_hms(seconds);
    let billable_marker = if billable { "$" } else { " " };
    let project_display = if project_name.is_empty() {
        String::new()
    } else {
        format!(" @{}", project_name.cyan())
    };
    let date_display = if start.len() >= 10 {
        &start[..10]
    } else {
        start
    };
    let id_display = match id {
        Some(i) => format!("{i:>10} "),
        None => "           ".to_string(),
    };

    println!(
        "{}{} {} [{}] {}{}",
        id_display.dimmed(),
        billable_marker.green().bold(),
        date_display.dimmed(),
        duration.green(),
        description,
        project_display,
    );
}

