use crate::api::client::ApiClient;
use crate::constants;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

pub struct StatsCommand;

fn aggregate_by_project(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals: HashMap<String, i64> = HashMap::new();
    for entry in entries.iter().filter(|entry| !entry.is_running()) {
        let project_name = entry
            .project
            .as_ref()
            .map(|project| project.name.clone())
            .unwrap_or_else(|| constants::NO_PROJECT.to_string());
        *totals.entry(project_name).or_default() += entry.duration;
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(name_a, seconds_a), (name_b, seconds_b)| {
        seconds_b.cmp(seconds_a).then_with(|| name_a.cmp(name_b))
    });
    totals
}

impl StatsCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = aggregate_by_project(&entries);
        let grand_total: i64 = totals.iter().map(|(_, seconds)| seconds).sum();

        for (project_name, seconds) in totals {
            println!(
                "{}  {}",
                utilities::format_duration_compact(seconds),
                project_name
            );
        }
        println!("{}  Total", utilities::format_duration_compact(grand_total));
        Ok(())
    }
}

